        // контрпримеры из причин
        case { assertEquals(1, binarySearch(intArrayOf(1, 3), 3)) }
        case { assertEquals(0, binarySearch(intArrayOf(1, 3), 1)) }
        case { assertEquals(1, binarySearch(intArrayOf(1, 3, 5, 7, 9), 3)) }
    }
}

