private object L1_2_v0 { // reference
    // Случай 1: "abacb" → 'c' (a и b повторяются)
    // Случай 2: "aabb" → null
    // Случай 3: "z" → 'z'
    fun firstUniqueChar(s: String): Char? {
        // символ -> сколько раз
        val counts = HashMap<Char, Int>()
        // 1-й проход: считаем частоты
        for (char in s) counts[char] = counts.getOrDefault(char, 0) + 1
        // 2-й проход: первый уникальный
        for (char in s) if (counts[char] == 1) return char
        // уникального символа нет
        return null
    }

    fun run() {
        case { assertEquals('c', firstUniqueChar("abacb")) }
        case { assertNull(firstUniqueChar("aabb")) }
        case { assertEquals('z', firstUniqueChar("z")) }
        case { assertNull(firstUniqueChar("")) }
        case { assertEquals('b', firstUniqueChar("ba")) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: первый символ с s.count == 1 (квадратичный подсчёт, без Map); все строки длины 0..5 из {a, b, c}
        for (n in 0..5) case {
            for (m in 0 until pw(3, n)) {
                val s = CharArray(n) { 'a' + (m / pw(3, it)) % 3 }.concatToString()
                assertEquals(s.firstOrNull { c -> s.count { it == c } == 1 }, firstUniqueChar(s))
            }
        }
        case { assertEquals('a', firstUniqueChar("abb")) } // уникальный первым
        case { assertEquals('b', firstUniqueChar("aab")) } // уникальный последним
        case { assertNull(firstUniqueChar("abcabc")) }
        // контрпримеры из причин
        case { assertNull(firstUniqueChar("aa")) }
        case { assertEquals('a', firstUniqueChar("ab")) }
    }
}

private object L1_3_v0 { // reference
    // Случай 1: "йцукен", "некуцй" → true
    // Случай 2: "ффффа", "фффа" → false
    // Случай 3: "ab", "ac" → false
    fun sameLetters(a: String, b: String): Boolean {
        // быстрая проверка длин
        if (a.length != b.length) return false
        // буква -> сколько раз
        val counts = HashMap<Char, Int>()
        // считаем буквы первого слова
        for (char in a) counts[char] = counts.getOrDefault(char, 0) + 1
        // вычитаем буквы второго слова
        for (char in b) {
            // остаток этой буквы
            val remaining = (counts[char] ?: 0) - 1
            // в b лишняя буква
            if (remaining < 0) return false
            counts[char] = remaining
        }
        // длины равны, минуса не было
        return true
    }

    fun run() {
        case { assertTrue(sameLetters("йцукен", "некуцй")) }
        case { assertFalse(sameLetters("ффффа", "фффа")) }
        case { assertFalse(sameLetters("ab", "ac")) }
        case { assertFalse(sameLetters("aab", "abb")) }
        case { assertTrue(sameLetters("", "")) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: сравнение отсортированных списков букв; все пары строк длины 0..3 из {a, b, c}
        val words = mutableListOf<String>()
        for (n in 0..3) for (m in 0 until pw(3, n)) words += CharArray(n) { 'a' + (m / pw(3, it)) % 3 }.concatToString()
        for (a in words) case {
            for (b in words) assertEquals(a.toList().sorted() == b.toList().sorted(), sameLetters(a, b))
        }
        case { assertFalse(sameLetters("", "a")) }
        case { assertFalse(sameLetters("abc", "abcc")) }
        // контрпримеры из причин
        case { assertTrue(sameLetters("ab", "ba")) }
        case { assertTrue(sameLetters("a", "a")) }
        case { assertTrue(sameLetters("aa", "aa")) }
        case { assertFalse(sameLetters("ab", "a")) }
        case { assertFalse(sameLetters("ab", "aa")) }
    }
}

private object L1_4_v0 { // reference
    // Случай 1: [2, 7, 11, 15], target = 9 → (0, 1)
    // Случай 2: [3, 2, 4], target = 6 → (1, 2)
    // Случай 3: [1, 2], target = 7 → null
    fun twoSum(nums: IntArray, target: Int): Pair<Int, Int>? {
        // значение -> индекс
        val seen = HashMap<Int, Int>()
        for (i in nums.indices) {
            // кого не хватает до target
            val need = target - nums[i]
            // пара найдена
            seen[need]?.let { return it to i }
            // потом запоминаем текущее
            seen[nums[i]] = i
        }
        // пары нет
        return null
    }

    fun run() {
        case { assertEquals(0 to 1, twoSum(intArrayOf(2, 7, 11, 15), 9)) }
        case { assertEquals(1 to 2, twoSum(intArrayOf(3, 2, 4), 6)) }
        case { assertEquals(0 to 1, twoSum(intArrayOf(3, 3), 6)) }
        case { assertNull(twoSum(intArrayOf(1, 2), 7)) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: перебор всех пар i < j; все массивы длины 0..4 из {-1, 0, 1, 2}, target -2..4
        for (n in 0..4) case {
            for (m in 0 until pw(4, n)) {
                val a = IntArray(n) { (m / pw(4, it)) % 4 - 1 }
                for (t in -2..4) {
                    var exists = false
                    for (i in a.indices) for (j in i + 1 until a.size) if (a[i] + a[j] == t) exists = true
                    val r = twoSum(a, t)
                    if (exists) assertTrue(r != null && r.first < r.second && a[r.first] + a[r.second] == t)
                    else assertNull(r)
                }
            }
        }
        case { assertNull(twoSum(intArrayOf(), 0)) }
        case { assertNull(twoSum(intArrayOf(3), 6)) } // target = 2·x, но индекс один
        case { assertEquals(0 to 2, twoSum(intArrayOf(-3, 4, 1), -2)) }
        case { assertEquals(0 to 2, twoSum(intArrayOf(0, 4, 0), 0)) }
        case { assertEquals(0 to 1, twoSum(intArrayOf(Int.MAX_VALUE, -1), Int.MAX_VALUE - 1)) }
        // контрпримеры из причин
        case { assertEquals(0 to 1, twoSum(intArrayOf(2, 7), 9)) }
    }
}

private object L1_5_v0 { // reference
    data class StepEntry(val userId: Int, val steps: Int)
    data class ChampionResult(val userIds: List<Int>, val steps: Int)

    // Случай 1: [[(1, 100), (2, 50)], [(1, 100), (2, 50)]]
    //   → [1], 200
    // Случай 2: [[(1, 100), (2, 500)], [(1, 100)]]
    //   → [1], 200 (2-й пропустил день)
    // Случай 3: [] → [], 0
    fun findChampions(statistics: List<List<StepEntry>>): ChampionResult {
        // сколько всего дней
        val totalDays = statistics.size
        // userId -> сумма шагов
        val totalSteps = HashMap<Int, Int>()
        // userId -> дней участия
        val daysActive = HashMap<Int, Int>()

        // один проход по всем записям
        for (day in statistics) for (entry in day) {
            totalSteps[entry.userId] = totalSteps.getOrDefault(entry.userId, 0) + entry.steps
            daysActive[entry.userId] = daysActive.getOrDefault(entry.userId, 0) + 1
        }

        // кто участвовал во все дни
        val allDaysUsers = daysActive.filterValues { it == totalDays }.keys
        // лучший результат среди них
        val maxSteps = allDaysUsers.maxOfOrNull { totalSteps[it] ?: 0 } ?: 0
        // все с максимумом
        val champions = allDaysUsers.filter { totalSteps[it] == maxSteps }
        return ChampionResult(champions, maxSteps)
    }

    fun run() {
        case { assertEquals(ChampionResult(listOf(1), 200), findChampions(listOf(listOf(StepEntry(1, 100), StepEntry(2, 50)), listOf(StepEntry(1, 100), StepEntry(2, 50))))) }
        case { assertEquals(ChampionResult(listOf(1), 200), findChampions(listOf(listOf(StepEntry(1, 100), StepEntry(2, 500)), listOf(StepEntry(1, 100))))) }
        case { findChampions(listOf(listOf(StepEntry(1, 100), StepEntry(2, 100)), listOf(StepEntry(2, 50), StepEntry(1, 50)))).let { assertEquals(listOf(1, 2), it.userIds.sorted()); assertEquals(150, it.steps) } }
        case { assertEquals(ChampionResult(emptyList(), 0), findChampions(emptyList())) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: перебор юзеров, «был во все дни» = есть запись в каждом дне (не счётчик);
        // все наборы из 0..3 дней, в дне юзер 1 и юзер 2 либо отсутствуют, либо с шагами 0 или 100
        fun oracle(st: List<List<StepEntry>>): Pair<List<Int>, Int> {
            val users = st.flatten().map { it.userId }.distinct()
            val full = users.filter { u -> st.all { day -> day.any { it.userId == u } } }
            val total = full.associateWith { u -> st.flatten().filter { it.userId == u }.sumOf { it.steps } }
            val best = total.values.maxOrNull() ?: 0
            return full.filter { total[it] == best }.sorted() to best
        }
        val opts = listOf(-1, 0, 100) // -1 = юзера в этот день нет
        for (d in 0..3) case {
            for (m in 0 until pw(9, d)) {
                val st = List(d) { k ->
                    val code = (m / pw(9, k)) % 9
                    listOf(1 to opts[code % 3], 2 to opts[code / 3]).filter { it.second >= 0 }.map { StepEntry(it.first, it.second) }
                }
                val r = findChampions(st)
                assertEquals(oracle(st), r.userIds.sorted() to r.steps)
            }
        }
        case { assertEquals(ChampionResult(listOf(1), 0), findChampions(listOf(listOf(StepEntry(1, 0))))) }
        case { assertEquals(ChampionResult(emptyList(), 0), findChampions(listOf(emptyList()))) } // день без записей
        // контрпримеры из причин
        case { assertEquals(ChampionResult(listOf(1), 100), findChampions(listOf(listOf(StepEntry(1, 100), StepEntry(2, 50))))) }
        case { assertEquals(ChampionResult(listOf(1), 100), findChampions(listOf(listOf(StepEntry(1, 100))))) }
        case { assertEquals(ChampionResult(listOf(1), 200), findChampions(listOf(listOf(StepEntry(1, 100)), listOf(StepEntry(1, 100))))) }
        case { assertEquals(ChampionResult(listOf(2), 100), findChampions(listOf(listOf(StepEntry(2, 100))))) }
    }
}

private object L2_1_v0 { // reference
    // Случай 1: [0, 1, 0, 3, 12] → [1, 3, 12, 0, 0]
    // Случай 2: [0] → [0]
    fun moveZeroes(nums: IntArray) {
        // куда писать ненулевой
        var slow = 0
        // fast бежит по всем
        for (fast in nums.indices) {
            // нули пропускаем
            if (nums[fast] != 0) {
                // копируем в slow
                nums[slow] = nums[fast]
                slow++
            }
        }
        // хвост добиваем нулями
        while (slow < nums.size) { tick()
            nums[slow] = 0
            slow++
        }
    }

    fun run() {
        case { assertContentEquals(intArrayOf(1, 3, 12, 0, 0), intArrayOf(0, 1, 0, 3, 12).also { moveZeroes(it) }) }
        case { assertContentEquals(intArrayOf(0), intArrayOf(0).also { moveZeroes(it) }) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: ненулевые в прежнем порядке, потом нули; все массивы длины 0..5 из {-1, 0, 1, 2}
        for (n in 0..5) case {
            for (m in 0 until pw(4, n)) {
                val a = IntArray(n) { (m / pw(4, it)) % 4 - 1 }
                val expected = a.filter { it != 0 } + a.filter { it == 0 }
                val got = a.copyOf()
                moveZeroes(got)
                assertEquals(expected, got.toList(), a.toList().toString())
            }
        }
        case { assertContentEquals(intArrayOf(), intArrayOf().also { moveZeroes(it) }) }
        case { assertContentEquals(intArrayOf(0, 0, 0), intArrayOf(0, 0, 0).also { moveZeroes(it) }) }
        case { assertContentEquals(intArrayOf(4, -2, 7), intArrayOf(4, -2, 7).also { moveZeroes(it) }) }
        case { assertContentEquals(intArrayOf(Int.MIN_VALUE, Int.MAX_VALUE, 0), intArrayOf(Int.MIN_VALUE, 0, Int.MAX_VALUE).also { moveZeroes(it) }) }
        // контрпримеры из причин
        case { assertContentEquals(intArrayOf(1, 0), intArrayOf(0, 1).also { moveZeroes(it) }) }
        case { assertContentEquals(intArrayOf(-1, 0), intArrayOf(-1, 0).also { moveZeroes(it) }) }
        case { assertContentEquals(intArrayOf(5, 0), intArrayOf(0, 5).also { moveZeroes(it) }) }
        case { assertContentEquals(intArrayOf(5), intArrayOf(5).also { moveZeroes(it) }) }
    }
}

private object L2_2_v0 { // reference
    // Случай 1: [1, 1, 2] → 2, начало [1, 2]
    // Случай 2: [0, 0, 1, 1, 1, 2, 2, 3, 3, 4]
    //   → 5, начало [0, 1, 2, 3, 4]
    fun removeDuplicates(nums: IntArray): Int {
        // пустой — уникальных нет
        if (nums.isEmpty()) return 0
        // nums[0] всегда остаётся
        var slow = 1
        // fast ищет новые значения
        for (fast in 1 until nums.size) {
            // не равно последнему?
            if (nums[fast] != nums[slow - 1]) {
                // пишем на место slow
                nums[slow] = nums[fast]
                slow++
            }
        }
        // длина без дубликатов
        return slow
    }

    fun run() {
        case { assertEquals(2, removeDuplicates(intArrayOf(1, 1, 2))) }
        case { assertContentEquals(intArrayOf(1, 2), intArrayOf(1, 1, 2).let { it.copyOf(removeDuplicates(it)) }) }
        case { assertContentEquals(intArrayOf(0, 1, 2, 3, 4), intArrayOf(0, 0, 1, 1, 1, 2, 2, 3, 3, 4).let { it.copyOf(removeDuplicates(it)) }) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: distinct() отсортированного массива; ответ k и первые k ячеек
        // все отсортированные массивы длины 0..6 из {0..3}
        for (n in 0..6) case {
            for (m in 0 until pw(4, n)) {
                val a = IntArray(n) { (m / pw(4, it)) % 4 }.also { it.sort() }
                val expected = a.distinct()
                val got = a.copyOf()
                val k = removeDuplicates(got)
                assertEquals(expected.size, k, a.toList().toString())
                assertEquals(expected, got.take(k), a.toList().toString())
            }
        }
        case { assertEquals(0, removeDuplicates(intArrayOf())) }
        case { assertContentEquals(intArrayOf(-3, 0, 7), intArrayOf(-3, -3, 0, 7, 7, 7).let { it.copyOf(removeDuplicates(it)) }) }
        case { assertContentEquals(intArrayOf(Int.MIN_VALUE, Int.MAX_VALUE), intArrayOf(Int.MIN_VALUE, Int.MAX_VALUE, Int.MAX_VALUE).let { it.copyOf(removeDuplicates(it)) }) }
        // контрпримеры из причин
        case { assertContentEquals(intArrayOf(1, 2), intArrayOf(1, 2).let { it.copyOf(removeDuplicates(it)) }) }
        case { assertContentEquals(intArrayOf(1, 2), intArrayOf(1, 1, 2).let { it.copyOf(removeDuplicates(it)) }) }
        case { assertEquals(1, removeDuplicates(intArrayOf(2, 2))) }
        case { assertEquals(1, removeDuplicates(intArrayOf(5, 5))) }
        case { assertEquals(1, removeDuplicates(intArrayOf(1))) }
    }
}

