private object L2_5_v0 { // reference
    // Случай 1: "abc", "ahbgdc" → true
    // Случай 2: "axc", "ahbgdc" → false
    fun isSubsequence(s: String, t: String): Boolean {
        // указатель в s
        var sIndex = 0
        // указатель в t
        var tIndex = 0
        // пока обе не кончились
        while (sIndex < s.length && tIndex < t.length) { tick()
            // совпало — двигаем s
            if (s[sIndex] == t[tIndex]) sIndex++
            // t двигается всегда
            tIndex++
        }
        // всю s нашли по порядку?
        return sIndex == s.length
    }

    fun run() {
        case { assertTrue(isSubsequence("abc", "ahbgdc")) }
        case { assertFalse(isSubsequence("axc", "ahbgdc")) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: перебор всех подпоследовательностей t по маске; все s и t из {a, b} длины 0..3 и 0..4
        for (sLen in 0..3) for (tLen in 0..4) case {
            for (x in 0 until pw(2, sLen)) for (y in 0 until pw(2, tLen)) {
                val s = (0 until sLen).map { "ab"[(x / pw(2, it)) % 2] }.joinToString("")
                val t = (0 until tLen).map { "ab"[(y / pw(2, it)) % 2] }.joinToString("")
                val expected = (0 until pw(2, tLen)).any { mask -> t.filterIndexed { i, _ -> (mask / pw(2, i)) % 2 == 1 } == s }
                assertEquals(expected, isSubsequence(s, t), "$s $t")
            }
        }
        case { assertTrue(isSubsequence("", "")) }
        case { assertTrue(isSubsequence("", "abc")) }
        case { assertFalse(isSubsequence("a", "")) }
        case { assertTrue(isSubsequence("abc", "abc")) }
        case { assertFalse(isSubsequence("aaa", "aa")) }
        case { assertFalse(isSubsequence("ab", "ba")) }
        // контрпримеры из причин
        case { assertTrue(isSubsequence("a", "a")) }
        case { assertTrue(isSubsequence("b", "ab")) }
        case { assertTrue(isSubsequence("ab", "abc")) }
    }
}

private object L2_6_v0 { // reference
    // Случай 1: [1, 12, -5, -6, 50, 3], k = 4 → 12.75
    // Случай 2: [5], k = 1 → 5.0
    fun findMaxAverage(nums: IntArray, k: Int): Double {
        // сумма первого окна
        var windowSum = 0
        for (i in 0 until k) windowSum += nums[i]
        // лучшая сумма пока что
        var maxSum = windowSum
        // сдвигаем окно на 1
        for (i in k until nums.size) {
            // вошёл новый, ушёл старый
            windowSum += nums[i] - nums[i - k]
            // запоминаем лучшее
            maxSum = maxOf(maxSum, windowSum)
        }
        // среднее с дробной частью
        return maxSum.toDouble() / k
    }

    fun run() {
        case { assertEquals(12.75, findMaxAverage(intArrayOf(1, 12, -5, -6, 50, 3), 4), 1e-9) }
        case { assertEquals(5.0, findMaxAverage(intArrayOf(5), 1), 1e-9) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: сумма каждого окна заново, лучшая / k; все массивы длины 1..5 из {-2..2}, все k
        for (n in 1..5) case {
            for (m in 0 until pw(5, n)) {
                val a = IntArray(n) { (m / pw(5, it)) % 5 - 2 }
                for (k in 1..n) {
                    val best = (0..n - k).maxOf { start -> (start until start + k).sumOf { a[it] } }
                    assertEquals(best.toDouble() / k, findMaxAverage(a.copyOf(), k), 1e-9, "${a.toList()} $k")
                }
            }
        }
        case { assertEquals(-1.5, findMaxAverage(intArrayOf(-3, -1, -2), 2), 1e-9) }
        case { assertEquals(0.0, findMaxAverage(intArrayOf(0, 0, 0), 3), 1e-9) }
        case { assertEquals(10000.0, findMaxAverage(IntArray(5) { 10000 }, 5), 1e-9) }
        case { assertEquals(5.0, findMaxAverage(intArrayOf(1, 2, 3, 4, 5, 6), 3), 1e-9) }
        // контрпримеры из причин
        case { assertEquals(-1.0, findMaxAverage(intArrayOf(-1), 1), 1e-9) }
        case { assertEquals(2.5, findMaxAverage(intArrayOf(1, 2, 3), 2), 1e-9) }
        case { assertEquals(2.0, findMaxAverage(intArrayOf(1, 2), 1), 1e-9) }
        case { assertEquals(2.0, findMaxAverage(intArrayOf(2, 1), 1), 1e-9) }
    }
}

private object L2_8_v0 { // reference
    // Случай 1: "abcabcbb" → 3 ("abc")
    // Случай 2: "bbbbb" → 1 ("b")
    // Случай 3: "pwwkew" → 3 ("wke")
    fun longestUnique(s: String): Int {
        // символ -> последний индекс
        val lastIndex = HashMap<Char, Int>()
        // левая граница окна
        var left = 0
        // лучшая длина пока что
        var best = 0
        // правая граница идёт по строке
        for (right in s.indices) {
            val prev = lastIndex[s[right]]
            // повтор внутри окна: ужимаем
            if (prev != null && prev >= left) left = prev + 1
            lastIndex[s[right]] = right
            // длина окна left..right
            best = maxOf(best, right - left + 1)
        }
        return best
    }

    fun run() {
        case { assertEquals(3, longestUnique("abcabcbb")) }
        case { assertEquals(1, longestUnique("bbbbb")) }
        case { assertEquals(3, longestUnique("pwwkew")) }
        case { assertEquals(0, longestUnique("")) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: перебор всех подстрок, длиннейшая без повторов (toSet); все строки длины 0..6 из {a, b, c, d}
        for (n in 0..6) case {
            for (m in 0 until pw(4, n)) {
                val s = CharArray(n) { 'a' + (m / pw(4, it)) % 4 }.concatToString()
                var best = 0
                for (i in 0..n) for (j in i..n) if (s.substring(i, j).toSet().size == j - i) best = maxOf(best, j - i)
                assertEquals(best, longestUnique(s), s)
            }
        }
        case { assertEquals(1, longestUnique(" ")) }
        case { assertEquals(3, longestUnique("dvdf")) }
        case { assertEquals(5, longestUnique("tmmzuxt")) }
        case { assertEquals(3, longestUnique("шалаш")) }
        case { assertEquals(26, longestUnique("abcdefghijklmnopqrstuvwxyz")) }
        // контрпримеры из причин
        case { assertEquals(1, longestUnique("aa")) }
        case { assertEquals(2, longestUnique("abba")) }
        case { assertEquals(2, longestUnique("abab")) }
        case { assertEquals(2, longestUnique("aab")) }
        case { assertEquals(1, longestUnique("aaa")) }
        case { assertEquals(1, longestUnique("a")) }
    }
}

private object L2_14_v0 { // reference
    // Случай 1: [2, 7, 11, 15], target = 9 → [1, 2]
    // Случай 2: [2, 3, 4], target = 6 → [1, 3]
    // Случай 3: [-1, 0], target = -1 → [1, 2]
    fun twoSumSorted(numbers: IntArray, target: Int): IntArray {
        // левый указатель — с начала
        var left = 0
        // правый указатель — с конца
        var right = numbers.size - 1
        // идём навстречу
        while (left < right) { tick()
            val sum = numbers[left] + numbers[right]
            // нашли пару: номера с единицы
            if (sum == target) return intArrayOf(left + 1, right + 1)
            // мало — левый вправо, много — правый влево
            if (sum < target) left++ else right--
        }
        // по условию пара всегда есть
        return intArrayOf()
    }

    fun run() {
        case { assertContentEquals(intArrayOf(1, 2), twoSumSorted(intArrayOf(2, 7, 11, 15), 9)) }
        case { assertContentEquals(intArrayOf(1, 3), twoSumSorted(intArrayOf(2, 3, 4), 6)) }
        case { assertContentEquals(intArrayOf(1, 2), twoSumSorted(intArrayOf(-1, 0), -1)) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: перебор пар; все неубывающие массивы длины 2..5 из чисел -2..2 и цели, у которых пара ровно одна
        for (n in 2..5) case {
            for (m in 0 until pw(5, n)) {
                val a = IntArray(n) { (m / pw(5, it)) % 5 - 2 }
                if ((1 until n).any { a[it] < a[it - 1] }) continue
                for (t in -4..4) {
                    val pairs = (0 until n).flatMap { i -> (i + 1 until n).filter { j -> a[i] + a[j] == t }.map { j -> intArrayOf(i + 1, j + 1) } }
                    if (pairs.size != 1) continue
                    assertContentEquals(pairs[0], twoSumSorted(a, t), a.joinToString() + " / " + t)
                }
            }
        }
        case { assertContentEquals(intArrayOf(2, 4), twoSumSorted(intArrayOf(2, 7, 11, 15), 22)) }
        case { assertContentEquals(intArrayOf(1, 2), twoSumSorted(intArrayOf(3, 3), 6)) }
        case { assertContentEquals(intArrayOf(3, 4), twoSumSorted(intArrayOf(1, 2, 5, 9), 14)) }
        case { assertContentEquals(intArrayOf(2, 3), twoSumSorted(intArrayOf(1, 2, 3, 9), 5)) }
    }
}

private object L2_15_v0 { // reference
    // Случай 1: "A man, a plan, a canal: Panama" → true
    // Случай 2: "race a car" → false
    // Случай 3: " " → true
    fun isValidPalindrome(s: String): Boolean {
        // левый указатель — с начала
        var left = 0
        // правый указатель — с конца
        var right = s.length - 1
        // идём навстречу
        while (left < right) { tick()
            // слева не буква и не цифра — пропускаем
            if (!s[left].isLetterOrDigit()) { left++; continue }
            // справа так же
            if (!s[right].isLetterOrDigit()) { right--; continue }
            // сравниваем без учёта регистра
            if (s[left].lowercaseChar() != s[right].lowercaseChar()) return false
            // оба указателя — к центру
            left++; right--
        }
        // все пары совпали
        return true
    }

    fun run() {
        case { assertTrue(isValidPalindrome("A man, a plan, a canal: Panama")) }
        case { assertFalse(isValidPalindrome("race a car")) }
        case { assertTrue(isValidPalindrome(" ")) }
        case { assertFalse(isValidPalindrome("0P")) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: оставить буквы и цифры, в нижний регистр, сравнить с разворотом; все строки длины 0..5 из {a, A, b, 0, пробел, запятая}
        val abc = "aAb0 ,"
        for (n in 0..5) case {
            for (m in 0 until pw(6, n)) {
                val s = CharArray(n) { abc[(m / pw(6, it)) % 6] }.concatToString()
                val t = s.filter { it.isLetterOrDigit() }.lowercase()
                assertEquals(t == t.reversed(), isValidPalindrome(s), s)
            }
        }
        case { assertTrue(isValidPalindrome("")) }
        case { assertTrue(isValidPalindrome(".,")) }
        case { assertTrue(isValidPalindrome("Шалаш!")) }
        // контрпримеры из причин
        case { assertFalse(isValidPalindrome(".ab")) }
        case { assertFalse(isValidPalindrome("ab.")) }
        case { assertTrue(isValidPalindrome(".a")) }
        case { assertFalse(isValidPalindrome("ab")) }
        case { assertTrue(isValidPalindrome("Aa")) }
    }
}

private object L3_2_v0 { // reference
    // Случай 1: "()[]{}" → true
    // Случай 2: "([)]" → false
    // Случай 3: "(" → false
    fun isValidBrackets(s: String): Boolean {
        // открытые, ждущие пары
        val stack = ArrayDeque<Char>()
        // закрывающая -> открывающая
        val pairs = mapOf(')' to '(', ']' to '[', '}' to '{')
        for (char in s) {
            // открывающая: в стек
            if (char in pairs.values) stack.addLast(char)
            // закрывающая: сверяем с вершиной
            else if (char in pairs.keys) {
                if (stack.isEmpty() || stack.removeLast() != pairs[char]) return false
            }
        }
        // все открытые закрылись
        return stack.isEmpty()
    }

    fun run() {
        case { assertTrue(isValidBrackets("()[]{}")) }
        case { assertFalse(isValidBrackets("([)]")) }
        case { assertFalse(isValidBrackets("(")) }
        case { assertTrue(isValidBrackets("{[()]}")) }
        case { assertTrue(isValidBrackets("")) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: прочие символы выкидываем, пары (), [], {} вычёркиваем, пока есть; пусто → true
        fun oracle(t: String): Boolean {
            var r = t.filter { it in "()[]{}" }
            repeat(t.length) { r = r.replace("()", "").replace("[]", "").replace("{}", "") }
            return r.isEmpty()
        }
        // все строки длины 0..6 из ()[]{}
        for (n in 0..6) case {
            for (m in 0 until pw(6, n)) {
                val s = CharArray(n) { "()[]{}"[(m / pw(6, it)) % 6] }.concatToString()
                assertEquals(oracle(s), isValidBrackets(s), s)
            }
        }
        // посторонние символы пропускаются: все строки длины 0..5 из ( ] x )
        for (n in 0..5) case {
            for (m in 0 until pw(4, n)) {
                val s = CharArray(n) { "(]x)"[(m / pw(4, it)) % 4] }.concatToString()
                assertEquals(oracle(s), isValidBrackets(s), s)
            }
        }
        case { assertTrue(isValidBrackets("a(b)c")) }
        case { assertTrue(isValidBrackets("([]{()})")) }
        case { assertFalse(isValidBrackets("((")) }
        case { assertFalse(isValidBrackets("))")) }
        case { assertFalse(isValidBrackets("(]")) }
        case { assertFalse(isValidBrackets("()(")) }
        // контрпримеры из причин
        case { assertFalse(isValidBrackets("(")) }
        case { assertTrue(isValidBrackets("()")) }
        case { assertFalse(isValidBrackets("([)]")) }
        case { assertFalse(isValidBrackets(")")) }
    }
}

private object L4_2_v0 { // reference
    // Случай 1: [-2, 1, -3, 4, -1, 2, 1, -5, 4]
    //   → 6 (подмассив [4, -1, 2, 1])
    // Случай 2: [1] → 1
    // Случай 3: [-3, -1, -2] → -1
    fun maxSubArray(nums: IntArray): Int {
        // лучшая сумма, кончающаяся на i
        var current = nums[0]
        // лучшая сумма вообще
        var best = nums[0]
        for (i in 1 until nums.size) {
            // продолжить серию или начать заново
            current = maxOf(nums[i], current + nums[i])
            best = maxOf(best, current)
        }
        return best
    }

    fun run() {
        case { assertEquals(6, maxSubArray(intArrayOf(-2, 1, -3, 4, -1, 2, 1, -5, 4))) }
        case { assertEquals(1, maxSubArray(intArrayOf(1))) }
        case { assertEquals(-1, maxSubArray(intArrayOf(-3, -1, -2))) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: перебор всех подмассивов; все массивы длины 1..5 из {-2..2}
        for (n in 1..5) case {
            for (m in 0 until pw(5, n)) {
                val a = IntArray(n) { (m / pw(5, it)) % 5 - 2 }
                var best = a[0]
                for (l in 0 until n) for (r in l until n) best = maxOf(best, (l..r).sumOf { a[it] })
                assertEquals(best, maxSubArray(a.copyOf()), "${a.toList()}")
            }
        }
        // оракул на длинных случайных массивах из {-100..100}
        case {
            repeat(50) {
                val a = IntArray(1 + rnd.nextInt(40)) { rnd.nextInt(201) - 100 }
                var best = a[0]
                for (l in a.indices) {
                    var sum = 0
                    for (r in l until a.size) {
                        sum += a[r]
                        best = maxOf(best, sum)
                    }
                }
                assertEquals(best, maxSubArray(a.copyOf()), "${a.toList()}")
            }
        }
        case { assertEquals(15, maxSubArray(intArrayOf(1, 2, 3, 4, 5))) } // весь массив
        case { assertEquals(-10000, maxSubArray(intArrayOf(-10000))) }
        case { assertEquals(0, maxSubArray(intArrayOf(-1, 0, -2))) }
        case { assertEquals(7, maxSubArray(intArrayOf(5, -1, 3))) } // через минус
        case { assertEquals(9, maxSubArray(intArrayOf(5, -9, 9))) } // начать заново
        // контрпримеры из причин
        case { assertEquals(3, maxSubArray(intArrayOf(1, 2))) }
        case { assertEquals(2, maxSubArray(intArrayOf(1, -1, 2))) }
        case { assertEquals(6, maxSubArray(intArrayOf(1, 2, 3))) }
        case { assertEquals(1, maxSubArray(intArrayOf(1, -1))) }
        case { assertEquals(5, maxSubArray(intArrayOf(5))) }
        case { assertEquals(-1, maxSubArray(intArrayOf(-1))) }
        case { assertEquals(-1, maxSubArray(intArrayOf(-1, -2))) }
        case { assertEquals(2, maxSubArray(intArrayOf(-1, 2))) }
    }
}

private object L5_1_v0 { // reference
    // Случай 1: n = 2 → 2 (1+1, 2)
    // Случай 2: n = 3 → 3 (1+1+1, 1+2, 2+1)
    // Случай 3: n = 5 → 8
    fun climbStairs(n: Int): Int {
        // 1 ступень — 1 способ, 2 — два
        if (n <= 2) return n
        // способов дойти до i-2 и до i-1
        var prev = 1
        var current = 2
        repeat(n - 2) {
            // на ступень i — с i-1 или с i-2
            val next = prev + current
            prev = current
            current = next
        }
        return current
    }

    fun run() {
        case { assertEquals(2, climbStairs(2)) }
        case { assertEquals(3, climbStairs(3)) }
        case { assertEquals(8, climbStairs(5)) }
        case { assertEquals(1, climbStairs(1)) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: список ways[i] = ways[i - 1] + ways[i - 2]; все n от 1 до 45
        case {
            val ways = IntArray(46)
            ways[0] = 1
            ways[1] = 1
            for (i in 2..45) ways[i] = ways[i - 1] + ways[i - 2]
            for (n in 1..45) assertEquals(ways[n], climbStairs(n), "n = $n")
        }
        // оракул 2: перебор шагов рекурсией в лоб; n от 1 до 20
        case {
            fun naive(k: Int): Int = if (k < 0) 0 else if (k == 0) 1 else naive(k - 1) + naive(k - 2)
            for (n in 1..20) assertEquals(naive(n), climbStairs(n), "n = $n")
        }
        case { assertEquals(1836311903, climbStairs(45)) } // максимум LeetCode, ещё влезает в Int
        // контрпримеры из причин
        case { assertEquals(1, climbStairs(1)) }
        case { assertEquals(2, climbStairs(2)) }
        case { assertEquals(3, climbStairs(3)) }
        case { assertEquals(5, climbStairs(4)) }
        case { assertEquals(8, climbStairs(5)) }
    }
}

private object BK6_1_v0 { // reference
    // Случай 1: ведро 2, 1 токен/с: 0 мс → true, 0 мс → true, 0 мс → false
    // Случай 2: ведро 1, 1 токен/с: 0 мс → true, 500 мс → false, 1000 мс → true
    // Случай 3: ведро 1, 2 токена/с: 0 мс → true, 500 мс → true
    class TokenBucket(private val capacity: Int, private val refillPerSec: Double) {
        // токенов в ведре сейчас (дробно)
        private var tokens = capacity.toDouble()
        // когда доливали в последний раз, мс
        private var lastMs = 0L

        // долить за прошедшее время
        private fun refill(nowMs: Long) {
            // сколько секунд прошло
            val elapsed = (nowMs - lastMs) / 1000.0
            // долив, но не выше ёмкости
            tokens = minOf(capacity.toDouble(), tokens + elapsed * refillPerSec)
            lastMs = nowMs
        }

        // пропустить запрос в момент nowMs?
        fun allow(nowMs: Long): Boolean {
            // сначала долить
            refill(nowMs)
            // меньше токена — отказ
            if (tokens < 1.0) return false
            // тратим один токен
            tokens -= 1.0
            return true
        }
    }

    fun run() {
        case { assertEquals(listOf(true, true, false), TokenBucket(2, 1.0).let { b -> listOf(b.allow(0), b.allow(0), b.allow(0)) }) }
        case { assertEquals(listOf(true, false, true), TokenBucket(1, 1.0).let { b -> listOf(b.allow(0), b.allow(500), b.allow(1000)) }) }
        case { assertEquals(listOf(true, true), TokenBucket(1, 2.0).let { b -> listOf(b.allow(0), b.allow(500)) }) }
        checks()
    }

    @Suppress("UNUSED_VARIABLE")
    private fun checks() {
        val rnd = kotlin.random.Random(1234)
        // оракул: миллитокены на Long; шаг времени кратен 250 мс, скорости 1/2/4 — ни одного округления в Double
        for (cap in 1..3) for (rate in listOf(1.0, 2.0, 4.0)) case {
            val b = TokenBucket(cap, rate)
            var milli = cap * 1000L
            var last = 0L
            var t = 0L
            for (i in 0 until 40) {
                t += (i * 7 % 5) * 250L
                milli = minOf(cap * 1000L, milli + (t - last) * rate.toLong())
                last = t
                val expected = milli >= 1000L
                if (expected) milli -= 1000L
                assertEquals(expected, b.allow(t), "cap=$cap rate=$rate t=$t")
            }
        }
        // ровно одна секунда — ровно один токен
        case { assertFalse(TokenBucket(1, 1.0).let { b -> b.allow(0); b.allow(999) }) }
        case { assertTrue(TokenBucket(1, 1.0).let { b -> b.allow(0); b.allow(1000) }) }
        // всплеск до ёмкости проходит, следующий нет
        case { assertEquals(listOf(true, true, true, false), TokenBucket(3, 1.0).let { b -> listOf(b.allow(5), b.allow(5), b.allow(5), b.allow(5)) }) }
        // долгая пауза не копит больше ёмкости
        case { assertEquals(listOf(true, true, false), TokenBucket(2, 1.0).let { b -> b.allow(0); b.allow(0); listOf(b.allow(60_000), b.allow(60_000), b.allow(60_000)) }) }
        // контрпримеры из причин
        case { assertTrue(TokenBucket(1, 1.0).allow(0)) }
        case { assertEquals(listOf(true, false), TokenBucket(1, 1.0).let { b -> listOf(b.allow(0), b.allow(0)) }) }
        case { assertEquals(listOf(true, false), TokenBucket(1, 1.0).let { b -> listOf(b.allow(0), b.allow(1)) }) }
        case { assertEquals(listOf(true, false, true), TokenBucket(1, 1.0).let { b -> listOf(b.allow(0), b.allow(0), b.allow(5000)) }) }
        case { assertEquals(listOf(true, true, false), TokenBucket(2, 1.0).let { b -> listOf(b.allow(0), b.allow(0), b.allow(0)) }) }
    }
}

